export type AnchorCollapseOrientation = 'horizontal' | 'vertical';
export interface AnchorItem {
    label: string;
    /**
     * Unique identity of the item. It keys the controlled `value`, the active highlight,
     * `aria-current`, and change event, so it must be unique across all items (including
     * nested children) — duplicates are inherently ambiguous.
     */
    value: string;
    href?: string;
    /**
     * Where to open `href`, mapped to the anchor's `target` attribute (e.g. `_blank`).
     * When it opens outside the current view (anything other than `_self`), clicking
     * the item does not update the active item.
     */
    target?: string;
    children?: AnchorItem[];
    /**
     * Called when this item is clicked, before the component updates the active item.
     * Receives the native MouseEvent; call `event.preventDefault()` to take over
     * navigation (e.g. SPA routing).
     *
     * Calling `preventDefault()` means "I'll handle this click": the component then
     * skips its own active-item update (and `ksChange`), so you own the active state —
     * typically by controlling the `value` prop (e.g. bound to the current route).
     * Without `preventDefault()`, the active item moves to this item and `ksChange` fires.
     */
    onClick?: (event: MouseEvent, item: AnchorItem) => void;
}
